import java.util.*;

class Solution {
  public int maximumNumberOfOnes(int width, int height, int sideLength, int maxOnes) {
    // a one at offset (i, j) inside the tile repeats across the whole matrix; take the offsets that repeat most
    List<Integer> counts = new ArrayList<>();
    for (int i = 0; i < sideLength; i++)
      for (int j = 0; j < sideLength; j++)
        counts.add(((width - i - 1) / sideLength + 1) * ((height - j - 1) / sideLength + 1));
    counts.sort(Collections.reverseOrder());
    int total = 0;
    for (int k = 0; k < maxOnes; k++) total += counts.get(k);
    return total;
  }
}
